const state={user:null,isAdmin:false,isModerator:false,role:"guest",founderId:"1552721267415584799",serverOwnerIds:["664656129770389545"],moderatorIds:[],betaIds:[],discordGuildId:"",discordInviteUrl:"",projects:[],rank:[],chatRank:[],users:[],forum:[],notifications:[],unreadMentions:0,coins:0,view:"home",liked:new Set(),socket:null};
