async function api(url,opts={}){const r=await fetch(url,{...opts,headers:{"Content-Type":"application/json",...(opts.headers||{})}});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||"Não foi possível concluir.");return data}
function openModal(html){modalContent.innerHTML=html;modal.classList.remove("hidden")}
