function requireLogin(){if(!state.user){openModal(`<div class="eyebrow">SUA CONTA OPendev</div><h2>Entre para participar.</h2><p>Você pode explorar a comunidade sem login. Para publicar projetos, curtir, mandar mensagens ou entrar em chamadas, conecte sua conta Discord.</p><button class="primary" id="modalLogin">Entrar com Discord ↗</button>`);$("#modalLogin").onclick=beginDiscordLogin;return false}return true}
function profileButton(){if(!state.user){$("#loginBtn").classList.remove("hidden");$("#userMenu").classList.add("hidden");return}$("#loginBtn").classList.add("hidden");const u=$("#userMenu");u.classList.remove("hidden");u.innerHTML=`<span>${state.user.avatar?`<img src="${esc(state.user.avatar)}" style="width:20px;height:20px;border-radius:50%;vertical-align:middle;margin-right:6px">`:"◉ "}${esc(state.user.username)} ▾</span>`;u.onclick=showProfileMenu}
function showProfileMenu(){openModal(`<div class="eyebrow">SUA CONTA</div><h2>Olá, ${esc(state.user.username)}</h2><p>Configure seu perfil ou saia da conta.</p><div class="form-actions"><button class="secondary" id="logoutBtn">Sair</button><button class="primary" id="editProfileBtn">Personalizar perfil</button></div>`);$("#logoutBtn").onclick=async()=>{await fetch("/auth/logout",{method:"POST"});location.reload()};$("#editProfileBtn").onclick=editProfile}
function editProfile(){openModal(`<div class="eyebrow">PERFIL PÚBLICO</div><h2>Personalizar perfil</h2><p>Escolha uma foto e um banner do seu computador. PNG, JPG, WEBP ou GIF.</p><form id="profileForm"><div class="form-field"><label>Nome público</label><input name="username" maxlength="32" value="${esc(state.user.username)}" required></div><div class="form-field"><label>Foto de perfil</label><input id="profileAvatarFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><small>Máximo 1,2 MB</small><div id="avatarFileName" class="file-hint">${state.user.avatar?'Foto atual selecionada':'Nenhuma foto nova selecionada'}</div></div><div class="form-field"><label>Banner do perfil</label><input id="profileBannerFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><small>Máximo 15 MB</small><div id="bannerFileName" class="file-hint">${state.user.banner?'Banner atual selecionado':'Nenhum banner novo selecionado'}</div></div><div class="form-field"><label>Bio</label><textarea name="bio" maxlength="180" placeholder="O que você está construindo?">${esc(state.user.bio||"")}</textarea></div><div class="form-field"><label>GitHub</label><input name="github" maxlength="100" value="${esc(state.user.github||"")}" placeholder="seu-usuario ou https://github.com/seu-usuario"></div><div class="form-actions"><button type="button" class="secondary" id="cancelProfile">Cancelar</button><button class="primary">Salvar perfil</button></div></form>`);let avatarData, bannerData;const readFile=(file,max)=>new Promise((resolve,reject)=>{if(!file)return resolve(undefined);if(!file.type.match(/^image\/(png|jpeg|webp|gif)$/))return reject(Error('Formato inválido. Use PNG, JPG, WEBP ou GIF.'));if(file.size>max)return reject(Error('A imagem é muito grande. Escolha um arquivo menor.'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file)});$('#profileAvatarFile').onchange=async e=>{try{avatarData=await readFile(e.target.files[0],1200*1024);$('#avatarFileName').textContent=e.target.files[0]?.name||'Nenhuma foto nova selecionada'}catch(err){toast(err.message);e.target.value=''}};$('#profileBannerFile').onchange=async e=>{try{bannerData=await readFile(e.target.files[0],15*1024*1024);$('#bannerFileName').textContent=e.target.files[0]?.name||'Nenhum banner novo selecionado'}catch(err){toast(err.message);e.target.value=''}};$('#cancelProfile').onclick=closeModal;$('#profileForm').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target);const payload={username:f.get('username'),bio:f.get('bio'),github:f.get('github')};if(avatarData!==undefined)payload.avatar=avatarData;if(bannerData!==undefined)payload.banner=bannerData;const d=await api('/api/profile',{method:'PATCH',body:JSON.stringify(payload)});state.user=d.user;profileButton();closeModal();toast('Perfil atualizado.');await refresh();renderRank()}catch(err){toast(err.message)}}}
function setView(view){state.view=view;if(view==="chat"&&state.user){state.unreadMentions=0;updateMentionBadge();state.socket?.emit("chat:mentions:read");}$(".quick-actions")?.classList.toggle("hidden",view!=="home");$$(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===view));const names={home:"Início",projects:"Projetos",rank:"DevRank",forum:"DevForum",calls:"Salas de voz",messages:"Mensagens",chat:"Chat geral",server:"Servidor Discord",missions:"Missões",shop:"Loja"};$("#pageTitle").textContent=names[view]||"Início";if(view==="home"){$(".welcome").classList.remove("hidden");$(".stats").classList.remove("hidden");$(".section-head").classList.remove("hidden");$("#projectGrid").classList.remove("hidden");$(".lower-grid").classList.remove("hidden");$("#sectionTitle").textContent="Projetos em destaque";$("#sectionSub").textContent="Os projetos mais curtidos aparecem primeiro. Ainda não há projetos — que tal inaugurar?";renderProjects();renderRankPreview()}else{$(".welcome").classList.add("hidden");$(".stats").classList.add("hidden");$(".section-head").classList.add("hidden");$(".lower-grid").classList.add("hidden");$("#projectGrid").classList.remove("hidden");if(view==="projects"){ $("#sectionTitle").textContent="Todos os projetos";renderProjects(true)}if(view==="rank")renderRank(true);if(view==="forum")renderForum();if(view==="calls")renderCalls();if(view==="messages")renderMessages();if(view==="chat")renderGeneralChat();if(view==="server")renderServer();if(view==="missions")renderMissions();if(view==="shop")renderShop()}}
