function setupHeatmap(){const cells=$$('.heatmap i');const today=new Date();cells.forEach((cell,index)=>{const daysAgo=(cells.length-1-index);const date=new Date(today);date.setDate(today.getDate()-daysAgo);const level=(index*7+Math.floor(index/3))%5;const count=[0,1,2,4,7][level];const label=date.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'});cell.dataset.level=String(level);cell.title=`${count} ${count===1?'atividade':'atividades'} · ${label}`;cell.setAttribute('role','button');cell.setAttribute('tabindex','0');cell.setAttribute('aria-label',cell.title);cell.addEventListener('click',()=>toast(`${cell.title}. A atividade detalhada aparece conforme a comunidade contribui.`));cell.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();cell.click()}})});const quick=document.createElement('section');quick.className='quick-actions panel';quick.innerHTML=`<div class="panel-head"><div><div class="eyebrow">SEU PRÓXIMO PASSO</div><h2>O que vamos construir hoje?</h2></div></div><div class="quick-action-grid"><button class="quick-action" data-quick="project"><span>⌘</span><b>Publicar projeto</b><small>Mostre o que está criando</small></button><button class="quick-action" data-quick="chat"><span>↗</span><b>Conversar ao vivo</b><small>Troque ideias no chat geral</small></button><button class="quick-action" data-quick="forum"><span>☷</span><b>Fazer uma pergunta</b><small>Peça ajuda à comunidade</small></button><button class="quick-action" data-quick="calls"><span>◉</span><b>Entrar numa call</b><small>Programe uma sessão de código</small></button></div>`;const stats=$('.stats');if(stats&&!$('.quick-actions'))stats.insertAdjacentElement('afterend',quick);quick.querySelectorAll('[data-quick]').forEach(b=>b.onclick=()=>{const v=b.dataset.quick;if(v==='project')newProject();else setView(v)})}
setupHeatmap();
async function beginDiscordLogin(){try{const c=await api("/api/config");if(!c.discordConfigured){openModal(`<div class="eyebrow">CONFIGURAÇÃO NECESSÁRIA</div><h2>Login Discord ainda não configurado</h2><p>Para ativar o login, preencha <code>DISCORD_CLIENT_ID</code> e <code>DISCORD_CLIENT_SECRET</code> no arquivo <code>.env</code>. No Discord Developer Portal, adicione exatamente <code>${esc(location.origin)}/auth/discord/callback</code> em Redirects e use essa mesma URL em <code>DISCORD_CALLBACK_URL</code>. Depois reinicie o servidor.</p><div class="form-actions"><button class="primary" id="loginSetupClose">Entendi</button></div>`);$('#loginSetupClose').onclick=closeModal;return;}location.href="/auth/discord";}catch(e){toast("Não foi possível verificar a configuração do login.")}}
