function renderServer(){const invite=state.discordInviteUrl||"https://discord.com";$('#projectGrid').innerHTML=`<section class="server-page server-page-compact"><article class="discord-invite-card"><div class="discord-invite-main"><img class="discord-invite-logo" src="/assets/server-logo.png" alt="Logo Servidor dos Programadores"><div class="discord-invite-info"><div class="discord-invite-title">Servidor dos Programadores <span class="official-badge"><span class="official-check">✓</span> OFICIAL</span></div><div class="discord-invite-stats"><span><i class="discord-online-dot"></i><b id="discordOnlineCount">—</b> online</span><span><i class="discord-member-dot"></i><b id="discordMemberCount">Comunidade</b></span></div></div></div><div class="discord-invite-description">O servidor oficial da comunidade de desenvolvedores. Converse, compartilhe projetos e aprenda com outros programadores.</div><div id="discordOnlineMembers" class="discord-online-members"><span class="discord-widget-loading">Carregando informações do servidor…</span></div><a class="discord-join-link" href="${esc(invite)}" target="_blank" rel="noreferrer">Entrar no servidor <span aria-hidden="true">↗</span></a></article></section>`;api('/api/discord-widget').then(data=>{const online=$('#discordOnlineCount'),members=$('#discordMemberCount'),list=$('#discordOnlineMembers');if(!online||!members||!list)return;online.textContent=Number.isFinite(data.presenceCount)?String(data.presenceCount):'—';members.textContent=data.approximateMemberCount?`${Number(data.approximateMemberCount).toLocaleString('pt-BR')} membros`:'Servidor Discord';if(Array.isArray(data.members)&&data.members.length){list.innerHTML=`<div class="discord-online-label"><i class="discord-online-dot"></i> Pessoas online</div><div class="discord-online-list">${data.members.slice(0,8).map(m=>`<span class="discord-online-person" title="${esc(m.username||'Membro online')}">${m.avatar_url?`<img src="${esc(m.avatar_url)}" alt="">`:`<span>${esc((m.username||'?').slice(0,1).toUpperCase())}</span>`}</span>`).join('')}</div>`}else{list.innerHTML='<span class="discord-widget-loading">Veja a comunidade no Discord.</span>'}}).catch(()=>{const list=$('#discordOnlineMembers');if(list)list.innerHTML='<span class="discord-widget-loading">Entre no servidor para conversar com a comunidade.</span>'})}
function renderGeneralChat(){if(!state.user){$('#projectGrid').innerHTML=`<div class="empty-state"><div class="empty-icon">☷</div><h3>Chat geral</h3><p>Entre com o Discord para conversar ao vivo com a comunidade.</p><button class="primary" id="chatLogin">Entrar com Discord</button></div>`;$('#chatLogin').onclick=()=>location.href='/auth/discord';return}$('#projectGrid').innerHTML=`<section class="general-chat panel"><div class="panel-head"><div><div class="eyebrow">COMUNIDADE AO VIVO</div><h2>Chat geral</h2><p class="chat-hint">Compartilhe dúvidas, imagens e GIFs com a comunidade.</p></div><span class="live-label"><i></i> Ao vivo</span></div><div id="generalMessages" class="general-messages"><p class="empty-inline">Carregando mensagens…</p></div><form id="generalChatForm" class="dm-compose general-compose"><input id="chatImageInput" type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><button type="button" class="attach-btn chat-attach-icon" id="chatAttachButton" title="Anexar imagem ou GIF" aria-label="Anexar imagem ou GIF"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 15-5-5L5 21"/></svg></button><div class="chat-input-wrap"><textarea name="body" id="generalChatInput" rows="1" maxlength="1000" placeholder="Escreva uma mensagem…" autocomplete="off"></textarea><div id="mentionSuggestions" class="mention-suggestions hidden" role="listbox"></div></div><button class="primary" type="submit">Enviar <span aria-hidden="true">↗</span></button><span id="chatFileName" class="chat-file-name"></span><div id="chatImagePreview" class="chat-image-preview hidden"></div></form></section>`;state.socket?.emit('chat:history');const fileInput=$('#chatImageInput'),preview=$('#chatImagePreview'),fileName=$('#chatFileName'),chatInput=$('#generalChatInput'),mentionBox=$('#mentionSuggestions');let mentionUsers=[];api('/api/users').then(list=>{mentionUsers=list||[];}).catch(()=>{});const updateMentions=()=>{const pos=chatInput.selectionStart,text=chatInput.value.slice(0,pos),match=text.match(/(?:^|\s)@([A-Za-z0-9_.-]{0,32})$/);if(!match||!mentionUsers.length){mentionBox.classList.add('hidden');return}const q=match[1].toLowerCase(),matches=mentionUsers.filter(u=>u.username.toLowerCase().includes(q)||String(u.tag||'').toLowerCase().includes(q)).slice(0,6);if(!matches.length){mentionBox.classList.add('hidden');return}mentionBox.innerHTML=matches.map(u=>`<button type="button" class="mention-option" data-mention-id="${esc(u.id)}" data-mention-name="${esc(u.tag||u.username.replace(/\s+/g,''))}">${u.avatar?`<img src="${esc(u.avatar)}" alt="">`:`<span class="mention-avatar">${esc(u.username.slice(0,1).toUpperCase())}</span>`}<span>${esc(u.username)}</span></button>`).join('');mentionBox.classList.remove('hidden');mentionBox.querySelectorAll('[data-mention-id]').forEach(b=>b.onclick=()=>{const start=chatInput.selectionStart,txt=chatInput.value.slice(0,start),m=txt.match(/(?:^|\s)@([A-Za-z0-9_.-]{0,32})$/);if(!m)return;const begin=start-m[0].length+(m[0].startsWith(' ')?1:0);chatInput.setRangeText('@'+b.dataset.mentionName+' ',begin,start,'end');mentionBox.classList.add('hidden');chatInput.focus()})};chatInput.addEventListener('input',updateMentions);chatInput.addEventListener('keydown',e=>{if(e.key==='Escape')mentionBox.classList.add('hidden');if(e.key==='Enter'&&!e.shiftKey&&!mentionBox.classList.contains('hidden')){const first=mentionBox.querySelector('[data-mention-id]');if(first){e.preventDefault();first.click()}}});$('#chatAttachButton').onclick=()=>fileInput.click();let imageData=null;fileInput.onchange=()=>{const file=fileInput.files?.[0];if(!file){imageData=null;preview.classList.add('hidden');fileName.textContent='';return}if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)){toast('Escolha PNG, JPG, WEBP ou GIF.');fileInput.value='';return}if(file.size>100*1024*1024){toast('A imagem precisa ter até 100 MB.');fileInput.value='';return}const reader=new FileReader();reader.onload=()=>{imageData={data:reader.result,name:file.name,type:file.type};preview.innerHTML=`<img src="${reader.result}" alt="Prévia do anexo"><button type="button" class="remove-attachment" aria-label="Remover anexo">×</button>`;preview.classList.remove('hidden');fileName.textContent=file.name;preview.querySelector('button').onclick=()=>{imageData=null;fileInput.value='';preview.classList.add('hidden');fileName.textContent=''}};reader.readAsDataURL(file)};$('#generalChatForm').onsubmit=e=>{e.preventDefault();const field=e.target.elements.body;const body=field.value.trim();if(!body&&!imageData)return;if(!state.socket?.connected){toast('Reconectando ao chat. Tente novamente em instantes.');return}state.socket.emit('chat:send',{body,image:imageData});field.value='';fileInput.value='';imageData=null;preview.classList.add('hidden');fileName.textContent=''}}
function generalMessageMarkup(m){const avatar=m.avatar?`<img class="general-avatar" src="${esc(m.avatar)}" alt="Foto de ${esc(m.username)}" loading="lazy">`:`<span class="general-avatar avatar-letter">${esc((m.username||'?').slice(0,1).toUpperCase())}</span>`;const media=m.image&&(/^data:image\/(png|jpeg|webp|gif);base64,/.test(m.image)||/^\/uploads\/[A-Za-z0-9._-]+$/.test(m.image))?`<a class="general-media-link" href="${esc(m.image)}" target="_blank" rel="noreferrer"><img class="general-media" src="${esc(m.image)}" alt="Imagem enviada por ${esc(m.username)}" loading="lazy"></a>`:'';return `<article class="general-message" data-user-id="${esc(m.userId)}"><div class="general-message-head">${avatar}<div class="general-author"><b data-username="${esc(m.username)}">${esc(m.username)} ${officialBadge(m.userId)} ${crown(m.userId)} ${betaBadge(m.userId)} ${topBadge(m.userId)}</b><time>${new Date(m.createdAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</time></div></div>${m.body?`<p>${renderChatBody(m.body)}</p>`:''}${media}${state.user&&(m.userId===state.user.id||state.isModerator)?`<button class="message-delete" data-delete-chat="${esc(m.id)}" title="Apagar mensagem">Apagar</button>`:''}</article>`}
function renderGeneralMessages(messages){const el=$('#generalMessages');if(!el)return;el.innerHTML=messages.length?messages.map(generalMessageMarkup).join(''):'<div class="dm-empty"><h3>O chat está tranquilo</h3><p>Seja a primeira pessoa a mandar uma mensagem.</p></div>';el.scrollTop=el.scrollHeight;bindChatDeleteButtons()}
