async function startCall(roomId,name){
 if(!requireLogin())return;
 openModal(`<div class="eyebrow">SALA DE VOZ</div><h2>${esc(name)}</h2><p>Áudio e compartilhamento de tela para todos os participantes conectados.</p><div id="callStatus" class="admin-note">Conectando…</div><div id="activeCallMembers" class="call-members"></div><div id="remoteMedia" class="remote-media"></div><div class="call-controls"><button id="muteCall"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5M8 22h8"/></svg>Mutar microfone</button><button id="shareCall"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8M12 17v4M12 13V7m-3 3 3-3 3 3"/></svg>Compartilhar tela</button><button id="leaveCall" class="danger"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M22 16.9v3a2 2 0 0 1-2.2 2A19.8 19.8 0 0 1 11.2 19a19.4 19.4 0 0 1-6-6A19.8 19.8 0 0 1 2.1 4.2 2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7l.5 2.8a2 2 0 0 1-.6 1.9L7.1 10a16 16 0 0 0 6 6l1.6-1.9a2 2 0 0 1 1.9-.6l2.8.5a2 2 0 0 1 1.6 1.9z"/></svg>Sair da sala</button></div><video id="screenPreview" autoplay muted playsinline style="width:100%;max-height:240px;background:#080808;border-radius:8px;display:none"></video>`);
 const socket=state.socket; let audioStream=null,screenStream=null,muted=false,closed=false; const peers=new Map(); const config={iceServers:[{urls:'stun:stun.l.google.com:19302'}]};
 const status=t=>{const el=$('#callStatus');if(el)el.textContent=t};
 const addRemote=(peerId,stream)=>{let v=document.querySelector(`[data-remote="${peerId}"]`);if(!v){v=document.createElement('video');v.dataset.remote=peerId;v.autoplay=true;v.playsInline=true;v.controls=true;v.setAttribute('aria-label','Áudio/vídeo remoto');$('#remoteMedia')?.appendChild(v)}v.srcObject=stream;v.style.display='block';v.play().catch(()=>{status('A mídia chegou. Se não ouvir, toque no player para ativar o áudio.')});};
 const negotiation=new Map();const pendingCandidates=new Map();
 const makePeer=(peerId,initiator)=>{if(peers.has(peerId))return peers.get(peerId);const pc=new RTCPeerConnection(config);peers.set(peerId,pc);if(audioStream)audioStream.getTracks().forEach(t=>pc.addTrack(t,audioStream));if(screenStream)screenStream.getTracks().forEach(t=>pc.addTrack(t,screenStream));pc.onicecandidate=e=>{if(e.candidate)socket.emit('rtc:signal',{to:peerId,roomId,signal:{candidate:e.candidate}})};pc.ontrack=e=>addRemote(peerId,e.streams[0]||new MediaStream([e.track]));pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState)){document.querySelector(`[data-remote="${peerId}"]`)?.remove()}};pc.onnegotiationneeded=async()=>{if(negotiation.get(peerId))return;negotiation.set(peerId,true);try{while(!closed&&pc.signalingState!=='stable')await new Promise(r=>setTimeout(r,80));if(closed||pc.signalingState!=='stable')return;await pc.setLocalDescription(await pc.createOffer());socket.emit('rtc:signal',{to:peerId,roomId,signal:{description:pc.localDescription}})}catch(e){console.warn('Falha ao negociar mídia:',e)}finally{negotiation.delete(peerId)}};return pc};
 const onJoined=async d=>{if(d.roomId!==roomId||d.socketId===socket.id)return;makePeer(d.socketId,false)};const onExisting=d=>{if(d.roomId===roomId)(d.peers||[]).forEach(pid=>makePeer(pid,true))};
 const onSignal=async d=>{if(d.roomId!==roomId)return;const pc=makePeer(d.from,false);try{if(d.signal.description){const desc=d.signal.description;const collision=desc.type==='offer'&&pc.signalingState!=='stable';const polite=String(socket.id)>String(d.from);if(collision&&!polite)return;if(collision&&polite)await pc.setLocalDescription({type:'rollback'});await pc.setRemoteDescription(desc);for(const c of pendingCandidates.get(d.from)||[]){await pc.addIceCandidate(c).catch(()=>{})}pendingCandidates.delete(d.from);if(desc.type==='offer'){await pc.setLocalDescription(await pc.createAnswer());socket.emit('rtc:signal',{to:d.from,roomId,signal:{description:pc.localDescription}})}}if(d.signal.candidate){if(pc.remoteDescription)await pc.addIceCandidate(d.signal.candidate);else{const list=pendingCandidates.get(d.from)||[];list.push(d.signal.candidate);pendingCandidates.set(d.from,list)}}}catch(e){console.warn('WebRTC signal:',e)}};
 const onLeft=d=>{const pc=peers.get(d.socketId);if(pc)pc.close();peers.delete(d.socketId);document.querySelector(`[data-remote="${d.socketId}"]`)?.remove()};
 const renderMembers=members=>{const html=members.length?members.map(m=>`<span class="call-member">${m.avatar?`<img src="${esc(m.avatar)}" alt="">`:''}<b data-username="${esc(m.username)}">${esc(m.username)} ${officialBadge(m.userId)} ${crown(m.userId)} ${betaBadge(m.userId)} ${topBadge(m.userId)}</b>${m.muted?'<span class="call-muted-indicator" title="Microfone mutado" aria-label="Microfone mutado">◖̸</span>':'<span class="call-unmuted-indicator" title="Microfone ativo" aria-label="Microfone ativo">◖</span>'}${m.userId===state.user.id?'<small>Você</small>':''}</span>`).join(''):'<span class="empty-presence">Ninguém na sala</span>';if($('#activeCallMembers'))$('#activeCallMembers').innerHTML=html;const list=$(`#members-${roomId}`);if(list)list.innerHTML=html};
 const onMembers=p=>{if(p?.roomId===roomId)renderMembers(p.members||[])};
 socket?.on('room:peer-joined',onJoined);socket?.on('room:existing-peers',onExisting);socket?.on('rtc:signal',onSignal);socket?.on('room:peer-left',onLeft);socket?.on('room:members',onMembers);socket?.emit('room:join',{roomId,username:state.user.username,userId:state.user.id,avatar:state.user.avatar});
 try{audioStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});status('Microfone conectado. O áudio será enviado aos participantes.');for(const [pid,pc] of peers){audioStream.getTracks().forEach(t=>{if(!pc.getSenders().some(sender=>sender.track===t))pc.addTrack(t,audioStream)})}}catch(e){status('Microfone bloqueado/indisponível. Permita o acesso ao microfone no navegador.');}
 const paintMute=()=>{const b=$('#muteCall');if(!b)return;b.classList.toggle('is-muted',muted);b.innerHTML=muted?'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5M8 22h8M3 3l18 18"/></svg> Microfone mutado':'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5M8 22h8"/></svg> Mutar microfone';socket?.emit('room:state',{roomId,state:{muted}})};$('#muteCall').onclick=()=>{muted=!muted;audioStream?.getAudioTracks().forEach(t=>t.enabled=!muted);paintMute()};
 const shareButton=$('#shareCall');if(!navigator.mediaDevices?.getDisplayMedia){shareButton.disabled=true;shareButton.title='Este navegador/dispositivo não permite compartilhar a tela. Tente no navegador de um computador.';shareButton.textContent='Tela indisponível neste dispositivo'}shareButton.onclick=async()=>{try{if(!navigator.mediaDevices?.getDisplayMedia)throw new Error('unsupported');screenStream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});const v=$('#screenPreview');v.srcObject=screenStream;v.style.display='block';for(const [pid,pc] of peers){for(const track of screenStream.getTracks()){if(!pc.getSenders().some(sender=>sender.track===track))pc.addTrack(track,screenStream)}}screenStream.getVideoTracks()[0]?.addEventListener('ended',()=>{const stopped=screenStream;if(!stopped)return;for(const pc of peers.values()){pc.getSenders().filter(sender=>sender.track&&stopped.getTracks().includes(sender.track)).forEach(sender=>{try{pc.removeTrack(sender)}catch{}})}stopped.getTracks().forEach(track=>track.stop());screenStream=null;if(v){v.srcObject=null;v.style.display='none'}status('Compartilhamento de tela encerrado.')});status('Solicitando envio da tela aos participantes…');}catch(e){console.warn('Compartilhamento de tela:',e);toast(e.message==='unsupported'?'Este dispositivo ou navegador não oferece compartilhamento de tela.':'Compartilhamento cancelado ou não permitido.')}};
 $('#leaveCall').onclick=()=>{if(closed)return;closed=true;audioStream?.getTracks().forEach(t=>t.stop());screenStream?.getTracks().forEach(t=>t.stop());peers.forEach(pc=>pc.close());peers.clear();socket?.emit('room:leave',{roomId});socket?.off('room:peer-joined',onJoined);socket?.off('room:existing-peers',onExisting);socket?.off('rtc:signal',onSignal);socket?.off('room:peer-left',onLeft);socket?.off('room:members',onMembers);closeModal()};
}
async function renderMessages(){if(!state.user){$("#projectGrid").innerHTML=`<div class="empty-state"><div class="empty-icon">✉</div><h3>Mensagens privadas</h3><p>Entre com o Discord para conversar com outros desenvolvedores.</p><button class="primary" id="messagesLogin">Entrar com Discord</button></div>`;$('#messagesLogin').onclick=()=>location.href='/auth/discord';return}$('#projectGrid').innerHTML=`<div class="dm-layout"><aside class="dm-sidebar"><div class="dm-heading"><div><div class="eyebrow">CAIXA DE ENTRADA</div><h2>Mensagens</h2></div><button id="newDm" class="primary">＋ Nova</button></div><input id="dmSearch" class="dm-search" placeholder="Buscar conversas"><div id="conversationList" class="conversation-list"><div class="empty-inline">Carregando conversas…</div></div><div class="dm-heading people-heading"><div><div class="eyebrow">COMUNIDADE</div><h2>Desenvolvedores</h2></div></div><div id="peopleList" class="conversation-list"></div></aside><section class="dm-chat" id="dmChat"><div class="dm-empty"><div class="empty-icon">✉</div><h3>Suas conversas</h3><p>Selecione uma pessoa para abrir o perfil e enviar uma mensagem.</p></div></section></div>`;await loadConversations();await loadPeople();$('#newDm').onclick=()=>{$('#peopleList').scrollIntoView({behavior:'smooth',block:'start'});$('#dmSearch').focus()};$('#dmSearch').oninput=()=>{const q=$('#dmSearch').value.toLowerCase();$$('.conversation-row').forEach(r=>r.classList.toggle('hidden',!r.textContent.toLowerCase().includes(q)))}}
async function loadConversations(){try{const list=await api('/api/dm/conversations');$('#conversationList').innerHTML=list.length?list.map(c=>`<button class="conversation-row" data-convo="${esc(c.user.id)}" data-name="${esc(c.user.username)}" data-avatar="${esc(c.user.avatar||'')}">${c.user.avatar?`<img src="${esc(c.user.avatar)}" alt="">`:`<span class="avatar-fallback">${esc(c.user.username.slice(0,1).toUpperCase())}</span>`}<span><b>${esc(c.user.username)} ${officialBadge(c.user.id)}</b><small>${esc(c.lastMessage?.body||(c.lastMessage?.image?'Foto enviada':'Comece uma conversa'))}</small></span></button>`).join(''):'<div class="empty-inline">Nenhuma conversa iniciada.</div>';$$('[data-convo]').forEach(b=>b.onclick=()=>openConversation(b.dataset.convo,b.dataset.name,b.dataset.avatar))}catch(e){$('#conversationList').innerHTML='<div class="empty-inline">Não foi possível carregar as conversas.</div>'}}
async function loadPeople(){try{const users=await api('/api/users');$('#peopleList').innerHTML=users.length?users.map(u=>`<button class="conversation-row" data-person="${esc(u.id)}" data-name="${esc(u.username)}" data-avatar="${esc(u.avatar||'')}">${u.avatar?`<img src="${esc(u.avatar)}" alt="">`:`<span class="avatar-fallback">${esc(u.username.slice(0,1).toUpperCase())}</span>`}<span><b>${esc(u.username)} ${crown(u.id)} ${betaBadge(u.id)} ${topBadge(u.id)}</b><small>${esc(u.bio||'Desenvolvedor')}</small></span><span class="person-open">Ver perfil</span></button>`).join(''):'<div class="empty-inline">Ainda não há outros perfis cadastrados.</div>';$$('[data-person]').forEach(b=>b.onclick=()=>openConversation(b.dataset.person,b.dataset.name,b.dataset.avatar))}catch(e){}}
async function openConversation(userId,username,avatar){if(!state.user){requireLogin();return}$('#dmChat').dataset.userId=userId;$('#dmChat').innerHTML=`<header class="dm-chat-head">${avatar?`<img src="${esc(avatar)}" alt="">`:`<span class="avatar-fallback">${esc(username.slice(0,1).toUpperCase())}</span>`}<div><b>${esc(username)} ${officialBadge(userId)} ${crown(userId)}</b><small>Mensagem privada</small></div><button id="dmCall" class="icon-btn" title="Ligar para esta pessoa" aria-label="Ligar"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4h4l2 5-2.5 1.5a15 15 0 0 0 5 5L15 13l5 2v4c0 1-1 1-2 1C10 20 4 14 4 6c0-1 0-2 1-2Z"/></svg></button><button id="viewDmProfile" class="secondary">Ver perfil</button></header><div id="dmMessages" class="dm-messages"><div class="empty-inline">Carregando mensagens…</div></div><form id="dmForm" class="dm-compose"><input id="dmImageFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif" hidden><button type="button" id="dmAttach" class="icon-btn dm-attach" title="Anexar foto" aria-label="Anexar foto"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="8.5" r="1.5"/><path d="m21 15-5-5L5 21"/></svg></button><div class="dm-compose-fields"><div id="dmImagePreview" class="dm-image-preview hidden"></div><textarea name="body" rows="1" maxlength="2000" placeholder="Escreva uma mensagem…"></textarea></div><button class="primary" type="submit">Enviar <span aria-hidden="true">↗</span></button></form>`;let imageData=null;$('#dmAttach').onclick=()=>$('#dmImageFile').click();$('#dmImageFile').onchange=()=>{const file=$('#dmImageFile').files[0];if(!file)return;if(!file.type.match(/^image\/(png|jpeg|webp|gif)$/)||file.size>1200*1024){toast('Escolha PNG, JPG, WEBP ou GIF de até 1,2 MB.');$('#dmImageFile').value='';return}const reader=new FileReader();reader.onload=()=>{imageData=reader.result;$('#dmImagePreview').classList.remove('hidden');$('#dmImagePreview').innerHTML=`<img src="${esc(imageData)}" alt="Prévia do anexo"><button type="button" id="removeDmImage" aria-label="Remover foto">×</button>`;$('#removeDmImage').onclick=()=>{imageData=null;$('#dmImageFile').value='';$('#dmImagePreview').classList.add('hidden');$('#dmImagePreview').innerHTML=''}};reader.readAsDataURL(file)};$('#dmCall').onclick=()=>{const pair=[state.user.id,userId].sort();closeModal();startCall('dm-'+pair.join('-'),`Chamada privada com ${username}`)};$('#viewDmProfile').onclick=async()=>{try{const u=await api(`/api/users/${encodeURIComponent(userId)}`);openProfile(u.id)}catch(e){toast(e.message)}};async function fetchMessages(){const msgs=await api(`/api/dm/${userId}`);$('#dmMessages').innerHTML=msgs.length?msgs.map(m=>{const own=m.from===state.user.id;const senderAvatar=own?state.user.avatar:(userId==="sdp-system"?"/assets/bot-official.png":avatar);return `<div class="dm-message-row ${own?'mine':''}" data-dm-message-row="${esc(m.id)}">${senderAvatar?`<img class="dm-message-avatar" src="${esc(senderAvatar)}" alt="">`:`<span class="dm-message-avatar dm-avatar-fallback">${esc((own?state.user.username:username).slice(0,1).toUpperCase())}</span>`}<div class="dm-message ${own?'mine':''} ${m.system?'system-message':''}" data-dm-message="${esc(m.id)}">${m.system?'<span class="official-message-label">'+officialBadge("sdp-system")+'</span>':''}${m.body?`<p>${renderChatBody(m.body)}</p>`:''}${m.image?`<a href="${esc(m.image)}" target="_blank" rel="noreferrer"><img class="dm-message-image" src="${esc(m.image)}" alt="Imagem enviada"></a>`:''}<small>${new Date(m.createdAt).toLocaleString('pt-BR')}</small>${!m.system&&(own||state.isModerator)?`<button class="message-delete" data-delete-dm="${esc(m.id)}" title="Apagar mensagem">Apagar</button>`:''}</div></div>`}).join(''):'<div class="dm-empty"><div class="empty-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6"/></svg></div><h3>Inicie a conversa</h3><p>Envie a primeira mensagem para ${esc(username)}.</p></div>';$('#dmMessages').scrollTop=$('#dmMessages').scrollHeight;$$('[data-delete-dm]').forEach(btn=>btn.onclick=async()=>{if(!confirm('Apagar esta mensagem?'))return;try{await api(`/api/dm/${userId}/${btn.dataset.deleteDm}`,{method:'DELETE'});await fetchMessages();toast('Mensagem apagada.')}catch(e){toast(e.message)}})}try{await fetchMessages()}catch(e){toast(e.message)}$('#dmForm').onsubmit=async e=>{e.preventDefault();const field=e.target.elements.body;const body=field.value.trim();if(!body&&!imageData)return;try{await api(`/api/dm/${userId}`,{method:'POST',body:JSON.stringify({body,image:imageData})});field.value='';imageData=null;$('#dmImageFile').value='';$('#dmImagePreview').classList.add('hidden');$('#dmImagePreview').innerHTML='';await fetchMessages();await loadConversations()}catch(err){toast(err.message)}}}

async function refresh(){try{const [projects,rank,forum,rankdev]=await Promise.all([api("/api/projects"),api("/api/rank"),api("/api/forum"),api("/api/rankdev")]);state.projects=projects;state.rank=rank;state.forum=forum;state.chatRank=rankdev.users||[];state.chatRankMonth=rankdev.month||"";renderProjects(state.view==="projects");renderRankPreview();if(state.view==="rank")renderRank(true);$$("[data-profile]").forEach(el=>el.onclick=()=>openProfile(el.dataset.profile));$("#statProjects").textContent=state.projects.length;$("#statDevs").textContent=state.rank.length;$("#statLikes").textContent=state.projects.reduce((n,p)=>n+p.likes,0)}catch(e){console.error(e)}}
async function loadNotifications(){if(!state.user)return;try{state.notifications=await api('/api/notifications');$('#notificationDot').classList.toggle('hidden',!state.notifications.length);$('#notificationList').innerHTML=state.notifications.length?state.notifications.slice().reverse().map(n=>`<div class="notification-item"><div class="notification-title-row"><b>${esc(n.title)}</b>${state.isAdmin?`<button class="delete-notification" data-delete-notification="${n.id}" title="Apagar notificação">×</button>`:''}</div><p>${esc(n.body)}</p><small>${new Date(n.createdAt).toLocaleString('pt-BR')}</small></div>`).join(''):'<p class="empty-inline">Nenhuma notificação por enquanto.</p>';$$('[data-delete-notification]').forEach(b=>b.onclick=async()=>{if(!confirm('Apagar esta notificação para todos?'))return;try{await api(`/api/admin/notifications/${b.dataset.deleteNotification}`,{method:'DELETE'});await loadNotifications();toast('Notificação apagada.')}catch(e){toast(e.message)}})}catch(e){}}

$("#notificationBtn").onclick=()=>{$("#notificationPanel").classList.toggle("hidden");loadNotifications()};$("#notificationClose").onclick=()=>$("#notificationPanel").classList.add("hidden");
$("#noticeClose").onclick=()=>$("#notice").classList.add("hidden");$("#discordNoticeLink").addEventListener("click",()=>{sessionStorage.setItem("discordNoticeVisited","1");$("#notice").classList.add("hidden")});if(sessionStorage.getItem("discordNoticeVisited")==="1")$("#notice").classList.add("hidden");
$("#searchInput").addEventListener("input",e=>{const q=e.target.value.toLowerCase();if(state.view!=="projects")setView("projects");const arr=state.projects.filter(p=>(p.title+" "+p.description+" "+p.language+" "+p.ownerName).toLowerCase().includes(q));const old=state.projects;state.projects=arr;renderProjects(true);state.projects=old});
const themeButton=$('.theme-toggle');function applyTheme(theme){document.documentElement.dataset.theme=theme;if(themeButton){themeButton.innerHTML=theme==='light'?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 14.2A8.5 8.5 0 0 1 9.8 3.5 8.5 8.5 0 1 0 20.5 14.2Z"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4.93 4.93l1.42 1.42m11.3 11.3 1.42 1.42M2 12h2m16 0h2M4.93 19.07l1.42-1.42m11.3-11.3 1.42-1.42"/></svg>'; themeButton.title=theme==='light'?'Modo claro':'Modo escuro';themeButton.setAttribute('aria-label',themeButton.title)}}let savedTheme='dark';try{savedTheme=localStorage.getItem('opendev-theme')||'dark'}catch{}applyTheme(savedTheme);themeButton?.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(next);try{localStorage.setItem('opendev-theme',next)}catch{}});
async function init(){try{const c=await api("/api/config");state.user=c.user;state.isAdmin=c.isAdmin;state.isModerator=!!c.isModerator;state.role=c.role||"guest";state.founderId=c.siteFounderId||c.founderId||"1552721267415584799";state.serverOwnerIds=c.serverOwnerIds||["664656129770389545"];state.moderatorIds=c.moderatorIds||[];state.betaIds=c.betaIds||[];state.ownerIds=c.ownerIds||[];state.discordGuildId=c.discordGuildId||"";state.discordInviteUrl=c.discordInviteUrl||"";profileButton();await refresh();await loadNotifications();if(state.user){try{state.users=await api("/api/users")}catch{}}if(["siteFounder","serverOwner"].includes(state.role)){const b=document.createElement("button");b.className="nav-item";b.dataset.view="admin";b.innerHTML='⚙ <span>Moderação</span>';$(".nav").append(b);b.onclick=()=>renderAdmin()}if(state.user)$("#memberCount").textContent=`Conta conectada`;else $("#memberCount").textContent="Visitante";}catch(e){console.error(e)}state.socket=io();state.socket.on("presence:update",renderPresence);state.socket.on("chat:history",renderGeneralMessages);state.socket.on('chat:mentions:count',d=>{state.unreadMentions=Number(d?.count||0);updateMentionBadge()});state.socket.on('chat:mention',d=>{if(!state.user||String(d.targetId)!==String(state.user.id))return;state.unreadMentions=state.view==='chat'?0:Number(d.count||state.unreadMentions+1);updateMentionBadge();if(state.view==='chat'){state.socket.emit('chat:mentions:read')}else{toast(`${d.fromUsername} mencionou você no chat geral`);if('Notification'in window&&Notification.permission==='granted'){try{new Notification('Menção no chat geral',{body:`${d.fromUsername}: ${d.body}`})}catch{}}}});state.socket.on("rankdev:update",d=>{state.chatRank=d?.users||[];state.chatRankMonth=d?.month||state.chatRankMonth;renderRankPreview();if(state.view==="rank")renderRank(true);if(state.view==="chat"){$$(".general-message").forEach(el=>{const name=el.querySelector(".general-author b");if(name){const uid=el.dataset.userId;if(uid)name.innerHTML=`${esc(name.dataset.username||name.textContent)} ${crown(uid)} ${betaBadge(uid)} ${topBadge(uid)}`}})}});state.socket.on("chat:deleted",d=>{document.querySelector(`[data-delete-chat=\"${d.id}\"]`)?.closest(".general-message")?.remove()});state.socket.on("forum:deleted",()=>{if(state.view==="forum")refresh().then(renderForum)});state.socket.on("user:removed",()=>{refresh();if(state.view==="messages")renderMessages()});state.socket.on("dm:deleted",d=>{document.querySelector(`[data-dm-message=\"${d.id}\"]`)?.remove();if(state.view==="messages")loadConversations()});state.socket.on("chat:new",m=>{api("/api/rankdev").then(d=>{state.chatRank=d.users||[];state.chatRankMonth=d.month||"";renderRankPreview();if(state.view==="rank")renderRank(true)}).catch(()=>{});if(state.view==="chat"){const el=$("#generalMessages");if(el){const wasAtBottom=el.scrollHeight-el.scrollTop-el.clientHeight<90;const empty=el.querySelector('.dm-empty');if(empty)empty.remove();el.insertAdjacentHTML('beforeend',generalMessageMarkup(m));while(el.querySelectorAll('.general-message').length>100)el.querySelector('.general-message')?.remove();bindChatDeleteButtons();if(wasAtBottom)el.scrollTop=el.scrollHeight}}});state.socket.on("room:created",()=>{if(state.view==="calls")renderCalls()});state.socket.on("room:members",payload=>{if(!payload?.roomId)return;const list=$(`#members-${payload.roomId}`);if(!list)return;const members=payload.members||[];list.innerHTML=members.length?members.map(m=>`<span class="call-member">${m.avatar?`<img src="${esc(m.avatar)}" alt="">`:""}<b>${esc(m.username)}</b>${m.muted?'<span class="call-muted-indicator" title="Mutado">◖̸</span>':'<span class="call-unmuted-indicator" title="Microfone ativo">◖</span>'}</span>`).join(""):`<span class="empty-presence">Ninguém na sala</span>`});state.socket.on("project:new",p=>{if(!state.projects.some(x=>x.id===p.id))state.projects.push(p);refresh()});state.socket.on("project:updated",refresh);state.socket.on("project:deleted",refresh);state.socket.on("notification:deleted",loadNotifications);state.socket.on("dm:new",m=>{if(state.user&&(m.from===state.user.id||m.to===state.user.id)&&state.view==="messages"){loadConversations();}});state.socket.on("notification:new",n=>{if(state.user){$("#notificationDot").classList.remove("hidden");toast("Nova notificação: "+n.title)}});if(state.user)state.socket.emit("chat:mentions:count",d=>{state.unreadMentions=Number(d?.count||0);updateMentionBadge()})}
async function renderAdmin(){if(!["siteFounder","serverOwner"].includes(state.role)){toast("O painel de moderação só está disponível para o fundador do site e o dono do servidor.");return}setView("admin");$("#projectGrid").innerHTML=`<div class="panel" style="grid-column:1/-1"><div class="eyebrow">ACESSO RESTRITO</div><h2>Painel administrativo</h2><p>O painel só é exibido para os IDs configurados no servidor. Nunca confie apenas em esconder um botão no navegador.</p><div class="admin-note">IDs autorizados via ADMIN_DISCORD_IDS e MODERATOR_DISCORD_IDS no arquivo .env.</div><form id="adminNoticeForm"><div class="form-field"><label>Título da notificação</label><input name="title" maxlength="100" required></div><div class="form-field"><label>Mensagem</label><textarea name="body" maxlength="500" required></textarea></div><button class="primary">Enviar notificação para todos</button></form><hr style="border-color:#282d29;margin:22px 0"><h3>Adicionar usuário conhecido</h3><p>O usuário precisa ter entrado pelo Discord pelo menos uma vez para aparecer no cadastro.</p><form id="adminUserForm"><div class="form-field"><label>ID Discord</label><input name="discordId" pattern="\\d{17,20}" required></div><button class="secondary">Verificar conta</button></form><div id="adminResult"></div></div>`;$("#adminNoticeForm").onsubmit=async e=>{e.preventDefault();try{await api("/api/admin/notifications",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();toast("Notificação enviada.");}catch(err){toast(err.message)}};$("#adminUserForm").onsubmit=async e=>{e.preventDefault();try{const d=await api("/api/admin/users",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$("#adminResult").innerHTML=`<p>Conta encontrada: <b>${esc(d.user.username)}</b> (${esc(d.user.id)})</p>`}catch(err){toast(err.message)}}}
